SELECT COUNT(DISTINCT o.customer_id) AS n
FROM orders o
WHERE o.created_at >= TIMESTAMP '2026-12-26';

SELECT o.id, o.amount
FROM orders o
WHERE o.customer_id = 12;

SELECT o.id, o.amount
FROM orders o
WHERE o.customer_id = 23;

SELECT * FROM emp e
WHERE NOT EXISTS (
    SELECT 1 FROM emp ee
    WHERE ee.job = e.job AND ee.sal = 34
);

SELECT * FROM emp e
WHERE e.sal = 4
   OR NOT EXISTS (SELECT 1 FROM dept d WHERE d.deptno = e.empno);

SELECT a + b AS x, b, a
FROM (VALUES (10,1),(30,7)) AS t(a,b)
WHERE a < b;
